using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Tools ---
var notebook = new Notebook();
var webSearcher = new WebSearcher();

var tools = new[]
{
    AIFunctionFactory.Create(webSearcher.SearchAsync),
    AIFunctionFactory.Create(webSearcher.FetchPageAsync),
    AIFunctionFactory.Create(notebook.AddNoteAsync),
    AIFunctionFactory.Create(notebook.GetNotesAsync),
};

// --- Build the chat client with automatic function invocation ---
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// --- System prompt ---
const string systemPrompt = """
    You are a research agent. The user will give you a topic to research.

    Your workflow:
    1. Use the search_web tool to find relevant information about the topic.
    2. Use the fetch_page tool to read promising pages from search results.
    3. Use the add_note tool to save important facts and findings as you go.
    4. Repeat searching and note-taking until you have a thorough understanding.
    5. Use the get_notes tool to review all your notes.
    6. Produce a final, well-structured summary of your findings with key points,
       citing sources where possible.

    Be thorough — perform multiple searches with different queries to cover
    the topic from different angles. Save at least 3-5 notes before summarizing.
    """;

// --- Main loop ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔍 AI Research Agent           ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research.          ║");
Console.WriteLine("║  Type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Research topic> ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic))
        continue;

    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();
    Console.WriteLine($"\n📚 Researching: {topic}\n");

    List<ChatMessage> messages =
    [
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}"),
    ];

    try
    {
        var response = await client.GetResponseAsync(messages, chatOptions);

        Console.WriteLine("═══════════════════════════════════════");
        Console.WriteLine("📝 RESEARCH SUMMARY");
        Console.WriteLine("═══════════════════════════════════════");
        Console.WriteLine(response.Text);
        Console.WriteLine("═══════════════════════════════════════\n");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"❌ Error: {ex.Message}\n");
    }
}

