+/// <summary>Provides web search via DuckDuckGo.</summary>
+sealed class WebSearcher
+{
+    private static readonly HttpClient Http = new()
+    {
+        DefaultRequestHeaders =
+        {
+            { "User-Agent", "ResearchAgent/1.0" }
+        },
+        Timeout = TimeSpan.FromSeconds(15),
+    };
+
+    [Description("Search the web for a query and return a list of result titles, URLs, and snippets.")]
+    public async Task<string> SearchAsync(
+        [Description("The search query string")] string query)
+    {
+        Console.WriteLine($"  🔎 Searching: \"{query}\"");
+
+        var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
+        var html = await Http.GetStringAsync(url);
+
+        var results = ParseDuckDuckGoResults(html);
+        if (results.Count == 0)
+            return "No results found.";
+
+        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
+    }
+
+    [Description("Fetch and return the text content of a web page URL (truncated to ~4000 chars).")]
+    public async Task<string> FetchPageAsync(
+        [Description("The full URL of the page to fetch")] string url)
+    {
+        Console.WriteLine($"  🌐 Fetching: {url}");
+
+        try
+        {
+            var html = await Http.GetStringAsync(url);
+            var text = StripHtmlTags(html);
+
+            // Truncate to keep token usage reasonable
+            return text.Length > 4000 ? text[..4000] + "\n...[truncated]" : text;
+        }
+        catch (Exception ex)
+        {
+            return $"Failed to fetch page: {ex.Message}";
+        }
+    }
+
+    private static List<SearchResult> ParseDuckDuckGoResults(string html)
+    {
+        var results = new List<SearchResult>();
+        var span = html.AsSpan();
+        const int maxResults = 8;
+
+        // Parse <a class="result__a" ...> blocks
+        while (results.Count < maxResults)
+        {
+            var markerIndex = span.IndexOf("class=\"result__a\"");
+            if (markerIndex < 0) break;
+            span = span[markerIndex..];
+
+            // Extract href
+            var hrefStart = span.IndexOf("href=\"");
+            if (hrefStart < 0) break;
+            span = span[(hrefStart + 6)..];
+            var hrefEnd = span.IndexOf("\"");
+            if (hrefEnd < 0) break;
+            var href = new string(span[..hrefEnd]);
+            span = span[hrefEnd..];
+
+            // Extract title (text between > and </a>)
+            var tagClose = span.IndexOf(">");
+            if (tagClose < 0) break;
+            span = span[(tagClose + 1)..];
+            var titleEnd = span.IndexOf("</a>");
+            if (titleEnd < 0) break;
+            var title = StripHtmlTags(new string(span[..titleEnd]));
+            span = span[titleEnd..];
+
+            // Try to find a snippet in nearby result__snippet
+            var snippet = "";
+            var snippetMarker = span.IndexOf("class=\"result__snippet\"");
+            var nextResult = span.IndexOf("class=\"result__a\"");
+            if (snippetMarker >= 0 && (nextResult < 0 || snippetMarker < nextResult))
+            {
+                var sSpan = span[snippetMarker..];
+                var sTagClose = sSpan.IndexOf(">");
+                if (sTagClose >= 0)
+                {
+                    sSpan = sSpan[(sTagClose + 1)..];
+                    var sEnd = sSpan.IndexOf("</");
+                    if (sEnd >= 0)
+                        snippet = StripHtmlTags(new string(sSpan[..sEnd]));
+                }
+            }
+
+            if (!string.IsNullOrWhiteSpace(title) && href.StartsWith("http", StringComparison.Ordinal))
+            {
+                // DuckDuckGo wraps URLs in a redirect — try to extract the real URL
+                if (href.Contains("uddg=", StringComparison.Ordinal))
+                {
+                    var uddgStart = href.IndexOf("uddg=", StringComparison.Ordinal) + 5;
+                    var uddgEnd = href.IndexOf('&', uddgStart);
+                    href = Uri.UnescapeDataString(
+                        uddgEnd > 0 ? href[uddgStart..uddgEnd] : href[uddgStart..]);
+                }
+
+                results.Add(new SearchResult(title.Trim(), href.Trim(), snippet.Trim()));
+            }
+        }
+
+        return results;
+    }
+
+    private static string StripHtmlTags(string html)
+    {
+        var chars = new char[html.Length];
+        var index = 0;
+        var inside = false;
+
+        foreach (var c in html)
+        {
+            switch (c)
+            {
+                case '<': inside = true; break;
+                case '>': inside = false; break;
+                default:
+                    if (!inside)
+                        chars[index++] = c;
+                    break;
+            }
+        }
+
+        var text = new string(chars, 0, index);
+        return System.Text.RegularExpressions.Regex
+            .Replace(text, @"\s+", " ")
+            .Trim();
+    }
+
+    private record SearchResult(string Title, string Url, string Snippet);
+}
