+/// <summary>In-memory notebook for storing research findings.</summary>
+sealed class Notebook
+{
+    private readonly List<Note> _notes = [];
+
+    [Description("Save a research note with a title and content. Use this to record important facts, quotes, or findings from your research.")]
+    public Task<string> AddNoteAsync(
+        [Description("Short title for the note")] string title,
+        [Description("The content/body of the note")] string content,
+        [Description("Source URL or reference (optional)")] string? source = null)
+    {
+        var note = new Note(title, content, source);
+        _notes.Add(note);
+        Console.WriteLine($"  📌 Note saved: \"{title}\"");
+        return Task.FromResult($"Note #{_notes.Count} saved: \"{title}\"");
+    }
+
+    [Description("Retrieve all research notes taken so far. Use this to review your findings before writing the final summary.")]
+    public Task<string> GetNotesAsync()
+    {
+        if (_notes.Count == 0)
+            return Task.FromResult("No notes have been taken yet.");
+
+        var output = _notes.Select((n, i) =>
+            $"Note #{i + 1}: {n.Title}\n{n.Content}" +
+            (n.Source is not null ? $"\nSource: {n.Source}" : ""))
+            .ToList();
+
+        Console.WriteLine($"  📋 Retrieved {_notes.Count} notes");
+        return Task.FromResult(string.Join("\n\n---\n\n", output));
+    }
+
+    public void Clear() => _notes.Clear();
+
+    private record Note(string Title, string Content, string? Source);
+}
